{"code": "import pandas as pd
import numpy as np

orders = pd.read_excel("DanhSachHoaDon.xlsx", sheet_name="Sheet1", usecols="A:K")
orders = orders[orders["Mã hóa đơn"].astype(str).str.strip() != "DANH SÁCH HÓA ĐƠN"]

def parse_d(m):
    s = str(m).strip()
    if re.match(r"^\d{5}$", s):
        # Excel serial date (epoch 1899-12-30)
        return pd.Timestamp(1899,12,30) + pd.Timedelta(days=int(s))
    try:
        return pd.to_datetime(m, dayfirst=True)
    except:
        return pd.NaT

orders["order_date"] = orders["Thời gian"].apply(parse_d)
print("Date range after conversion:", orders["order_date"].min(), "->", orders["order_date"].max())
print()
# Check the numeric ones map to reasonable dates
numeric = orders[orders["Thời gian"].astype(str).str.match(r"^\d{5}$")]["order_date"]
print("Numeric serial date range:", numeric.min(), "->", numeric.max())
print()
print("Sample conversions:")
for v in [45689, 45690, 45700]:
    print(v, "->", pd.Timestamp(1899,12,30) + pd.Timedelta(days=v))
"}

